package com.gregtech.gregtech.client;
import com.gregtech.gregtech.registry.GTConstructionBlocks;import com.gregtech.gregtech.block.misc.*;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.api.distmarker.Dist;import net.neoforged.neoforge.client.event.RegisterColorHandlersEvent;
@EventBusSubscriber(modid = com.gregtech.gregtech.api.mod.GregTechIdentity.MOD_ID,bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)
public final class ConstructionClientSetup {
 @SubscribeEvent public static void blocks(RegisterColorHandlersEvent.Block e){for(var b:java.util.List.of(GTConstructionBlocks.CONCRETE,GTConstructionBlocks.CONCRETE_REINFORCED))e.register((s,l,p,t)->t==0?ConcreteBlock.tint(s.getValue(ConcreteBlock.COLOR)):0xFFFFFF,b.get());for(var b:java.util.List.of(GTConstructionBlocks.GLASS_CLEAR,GTConstructionBlocks.GLASS_GLOW))e.register((s,l,p,t)->t==0?ConcreteBlock.tint(s.getValue(ColoredGlassBlock.COLOR)):0xFFFFFF,b.get());}
 @SubscribeEvent public static void items(RegisterColorHandlersEvent.Item e){for(var b:java.util.List.of(GTConstructionBlocks.CONCRETE,GTConstructionBlocks.CONCRETE_REINFORCED))e.register((s,t)->t==0?ConcreteBlock.tint(ConcreteBlock.itemColor(s)):0xFFFFFF,b.get().asItem());for(var b:java.util.List.of(GTConstructionBlocks.GLASS_CLEAR,GTConstructionBlocks.GLASS_GLOW))e.register((s,t)->t==0?ConcreteBlock.tint(ColoredGlassBlock.itemColor(s)):0xFFFFFF,b.get().asItem());}
 @SubscribeEvent public static void setup(net.neoforged.fml.event.lifecycle.FMLClientSetupEvent e){e.enqueueWork(()->{net.minecraft.client.renderer.ItemBlockRenderTypes.setRenderLayer(GTConstructionBlocks.GLASS_CLEAR.get(),net.minecraft.client.renderer.RenderType.translucent());net.minecraft.client.renderer.ItemBlockRenderTypes.setRenderLayer(GTConstructionBlocks.GLASS_GLOW.get(),net.minecraft.client.renderer.RenderType.translucent());});}
}
